"use client";

import {
  createContext,
  type FieldsetHTMLAttributes,
  type InputHTMLAttributes,
  type ReactNode,
  use,
  useId,
  useState,
} from "react";
import { cx } from "../utils/cx";

type RadioContextValue = { name: string; value: string; select: (value: string) => void; disabled?: boolean };
const RadioContext = createContext<RadioContextValue | null>(null);

export type RadioGroupProps = Omit<FieldsetHTMLAttributes<HTMLFieldSetElement>, "onChange" | "defaultValue"> & {
  /** The group's visible name (a `legend`). */
  legend: ReactNode;
  hideLegend?: boolean;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  name?: string;
  orientation?: "vertical" | "horizontal";
};

/**
 * A single choice from a few options, on native radio inputs: the browser provides arrow-key movement, a single tab
 * stop and form submission. Use `SegmentedControl` for view filters and `Select` for long lists.
 */
export function RadioGroup({
  legend,
  hideLegend,
  value: controlled,
  defaultValue = "",
  onValueChange,
  name,
  orientation = "vertical",
  disabled,
  className,
  children,
  ...rest
}: RadioGroupProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const value = controlled ?? uncontrolled;
  const auto = useId();
  const select = (v: string) => {
    if (controlled === undefined) setUncontrolled(v);
    onValueChange?.(v);
  };
  return (
    <RadioContext value={{ name: name ?? `hm-radio-${auto}`, value, select, disabled }}>
      <fieldset
        {...rest}
        disabled={disabled}
        className={cx("hm-radio-group", className)}
        data-orientation={orientation}
      >
        <legend className={cx("hm-radio-legend", hideLegend && "hm-sr-only")}>{legend}</legend>
        <div className="hm-radio-options">{children}</div>
      </fieldset>
    </RadioContext>
  );
}

export type RadioProps = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "type" | "name" | "checked" | "defaultChecked" | "value"
> & {
  value: string;
  label: ReactNode;
  /** Secondary text under the label, linked with aria-describedby. */
  description?: ReactNode;
};

export function Radio({ value, label, description, className, onChange, id, ...rest }: RadioProps) {
  const ctx = use(RadioContext);
  if (!ctx) throw new Error("<Radio> must be inside <RadioGroup>");
  const auto = useId();
  const inputId = id ?? `hm-radio-opt-${auto}`;
  const descId = description ? `${inputId}-desc` : undefined;
  return (
    <label className={cx("hm-radio", className)} htmlFor={inputId}>
      <input
        {...rest}
        id={inputId}
        type="radio"
        name={ctx.name}
        value={value}
        className="hm-radio-input"
        checked={ctx.value === value}
        disabled={rest.disabled ?? ctx.disabled}
        aria-describedby={descId}
        onChange={(e) => {
          onChange?.(e);
          if (e.target.checked) ctx.select(value);
        }}
      />
      <span className="hm-radio-text">
        <span className="hm-radio-label">{label}</span>
        {description ? (
          <span id={descId} className="hm-radio-description">
            {description}
          </span>
        ) : null}
      </span>
    </label>
  );
}
